pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        // Restrict input to avoid zero address (external call will fail with gas stipend issues)
        vm.assume(recipient != address(0));
        // Fund the contract so it can send ether if needed (bonus is 100 wei)
        vm.deal(address(c), 100);
        // Call the entry point
        c.getFirstWithdrawalBonus(recipient);
        // General rule: after calling getFirstWithdrawalBonus, the rewards for that recipient are zero.
        // (This holds for the reference because withdrawReward resets rewards to 0 before the call;
        //  the buggy version skips that reset, so rewards remain 100.)
        // Since rewardsForA is private and not directly readable, we rely on the public state:
        // withdrawReward can only be called via getFirstWithdrawalBonus, and after that,
        // calling withdrawReward again should succeed only if rewardsForA[recipient] > 0.
        // But we need a public getter. The public mapping rewardsForA is not defined; we use a trick:
        // We call withdrawReward again and check if it reverts. If it reverts, rewards are zero.
        // This is the only way to observe the effect through the public interface.
        // So the rule: after getFirstWithdrawalBonus, calling withdrawReward on the same recipient reverts.
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", recipient));
        assertTrue(!success, "Second withdrawReward should revert in reference, but bug may allow it");
    }
}

