        // In the reference contract, the lock is released, so this should succeed.
        // In the mutant, the lock remains true, so this call reverts.
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("withdrawReward(address)", recipient)
        );

        // For the reference version, success should be true.
