pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        uint256 initialRecipientBalance = recipient.balance;
        // Fund recipient with some ether to avoid underflow concerns
        vm.deal(recipient, 1 ether);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        if (ok) {
            assertTrue(recipient.balance == initialRecipientBalance + 100);
        } else {
            // If revert, no change should have occurred
            assertTrue(recipient.balance == initialRecipientBalance);
        }
    }
}
